/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const servers = [];

  async function scan(host) {
    if (visited.has(host)) return;
    visited.add(host);

    const hasRoot = ns.hasRootAccess(host);
    if (!hasRoot) return;

    const reqHack = ns.getServerRequiredHackingLevel(host);
    const maxMoney = ns.getServerMaxMoney(host);
    const currMoney = ns.getServerMoneyAvailable(host);
    const minSec = ns.getServerMinSecurityLevel(host);
    const currSec = ns.getServerSecurityLevel(host);
    const maxRam = ns.getServerMaxRam(host);

    if (maxMoney > 0) {
      servers.push({
        host,
        reqHack,
        maxMoney,
        currMoney,
        minSec,
        currSec,
        maxRam
      });
    }

    const peers = ns.scan(host);
    for (const peer of peers) {
      await scan(peer);
    }
  }

  await scan('home');

  servers.sort((a, b) => b.maxMoney - a.maxMoney);

  let first = true;
  for (const s of servers) {
    const pct = ((s.currMoney / s.maxMoney) * 100).toFixed(1);
    const line = `${s.host} | hack:${s.reqHack} | max:${s.maxMoney} | cur:${pct}% | sec:${s.minSec}/${s.currSec} | ram:${s.maxRam}`;
    if (first) {
      ns.tprint(`>>> ${line}`);
      first = false;
    } else {
      ns.print(line);
    }
  }
}
